function decodeString(hex) {
  if (!hex || hex === "0x") return null;
  const buf = Buffer.from(hex.slice(2), "hex");
  if (buf.length >= 64) {
    const len = buf.readUInt32BE(60);
    return buf.slice(64, 64 + len).toString("utf8");
  }
  return buf.toString("utf8");
}
