              <Button onClick={createAccount} disabled={loading} className="w-full">
                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Create Smart Account
              </Button>
            ) : (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label>Smart Wallet Address</Label>
                  <Alert>
                    <AlertDescription className="font-mono break-all">{account.address}</AlertDescription>
                  </Alert>
                </div>
                <div className="space-y-2">
                  <Label>Owner Address</Label>
                  <Alert>
                    <AlertDescription className="font-mono break-all">{account.owner}</AlertDescription>
                  </Alert>
                </div>
              </div>
            )}
          </TabsContent>
          <TabsContent value="transfer" className="space-y-4">
            <div className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="recipient">Recipient Address</Label>
                <Input id="recipient" placeholder="0x..." value={recipientAddress} onChange={(e) => setRecipientAddress(e.target.value)} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="amount">Amount (USDC)</Label>
                <Input id="amount" type="number" placeholder="0.00" value={amount} onChange={(e) => setAmount(e.target.value)} />
              </div>
              <Button onClick={transfer} disabled={loading || !recipientAddress || !amount} className="w-full">
                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Transfer USDC
              </Button>
            </div>
          </TabsContent>
        </Tabs>
        {status && (
          <Alert className="mt-4">
            <AlertDescription>{status}</AlertDescription>
          </Alert>
        )}
      </CardContent>
    </Card>
  </div>
</>
) }

````

